{"command": "mkdir -p /tmp/gen && cat > /tmp/gen/main.go <<'EOF'
package main

import (
	"image"
	"image/color"
	"image/gif"
	"image/jpeg"
	"image/png"
	"os"
)

func main() {
	w, h := 40, 20
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			r := uint8(x * 255 / (w - 1))
			g := uint8(y * 255 / (h - 1))
			b := uint8(128)
			img.Set(x, y, color.RGBA{r, g, b, 255})
		}
	}
	f, _ := os.Create("/tmp/t/test.png")
	png.Encode(f, img)
	f.Close()
	f, _ = os.Create("/tmp/t/test.jpg")
	jpeg.Encode(f, img, nil)
	f.Close()

	// gif with 2 frames
	g := &gif.GIF{Delay: []int{10, 10}, LoopCount: 0}
	g.Image = append(g.Image, img)
	img2 := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img2.Set(x, y, color.RGBA{uint8(255 - x*255/(w-1)), uint8(255 - y*255/(h-1)), 128, 255})
		}
	}
	g.Image = append(g.Image, img2)
	f, _ = os.Create("/tmp/t/test.gif")
	gif.EncodeAll(f, g)
	f.Close()
}
EOF
cd /tmp/gen && go mod init gen >/dev/null 2>&1; go run main.go && ls -la /tmp/t"}

