//go:build ignore
package main

import (
	"image"
	"image/color"
	"image/png"
	"os"
)

func save(name string, w, h int, col func(x, y int) color.Color) {
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			img.Set(x, y, col(x, y))
		}
	}
	f, _ := os.Create("/tmp/t/" + name)
	png.Encode(f, img)
	f.Close()
}

func main() {
	n := 16
	save("rampred.png", n, 1, func(x, y int) color.Color {
		return color.RGBA{uint8(x * 255 / (n - 1)), 0, 0, 255}
	})
	save("rampgray.png", n, 1, func(x, y int) color.Color {
		v := uint8(x * 255 / (n - 1))
		return color.RGBA{v, v, v, 255}
	})
	save("rampgreen.png", n, 1, func(x, y int) color.Color {
		return color.RGBA{0, uint8(x * 255 / (n - 1)), 0, 255}
	})
	save("rampblue.png", n, 1, func(x, y int) color.Color {
		return color.RGBA{0, 0, uint8(x * 255 / (n - 1)), 255}
	})
}
EOF
