//go:build ignore
package main

import (
	"image"
	"image/color"
	"image/png"
	"os"
	"fmt"
)

func main() {
	n := 16
	vals := []color.RGBA{}
	for i := 0; i < n; i++ {
		v := uint8(i * 255 / (n - 1))
		vals = append(vals, color.RGBA{v, 0, 0, 255})
	}
	// also gray values
	grays := []color.Gray{}
	for i := 0; i < n; i++ {
		grays = append(grays, color.Gray{uint8(i * 255 / (n - 1))})
	}
	for i := 0; i < n; i++ {
		img := image.NewRGBA(image.Rect(0, 0, 8, 8))
		for y := 0; y < 8; y++ {
			for x := 0; x < 8; x++ {
				img.Set(x, y, vals[i])
			}
		}
		f, _ := os.Create(fmt.Sprintf("/tmp/t/red%02d.png", i))
		png.Encode(f, img)
		f.Close()
		img2 := image.NewRGBA(image.Rect(0, 0, 8, 8))
		for y := 0; y < 8; y++ {
			for x := 0; x < 8; x++ {
				img2.Set(x, y, color.RGBA{grays[i].Y, grays[i].Y, grays[i].Y, 255})
			}
		}
		f, _ = os.Create(fmt.Sprintf("/tmp/t/gray%02d.png", i))
		png.Encode(f, img2)
		f.Close()
	}
}
EOF
