//go:build ignore
package main

import (
	"image"
	"image/color"
	"image/png"
	"os"
)

func ramp(name string, fn func(v uint8) color.Color) {
	img := image.NewRGBA(image.Rect(0, 0, 256, 1))
	for x := 0; x < 256; x++ {
		img.Set(x, 0, fn(uint8(x)))
	}
	f, _ := os.Create("/tmp/t/" + name)
	png.Encode(f, img)
	f.Close()
}

func main() {
	ramp("allred.png", func(v uint8) color.Color { return color.RGBA{v, 0, 0, 255} })
	ramp("allgreen.png", func(v uint8) color.Color { return color.RGBA{0, v, 0, 255} })
	ramp("allblue.png", func(v uint8) color.Color { return color.RGBA{0, 0, v, 255} })
	ramp("allgray.png", func(v uint8) color.Color { return color.RGBA{v, v, v, 255} })
	ramp("allalpha.png", func(v uint8) color.Color { return color.RGBA{255, 255, 255, v} })
	ramp("allwhitealpha.png", func(v uint8) color.Color { return color.RGBA{v, v, v, v} })
