package main

import (
	"fmt"
	"image"
	"image/color"
	"image/draw"
	"image/png"
	"os"
)

func load(p string) image.Image {
	f, err := os.Open(p)
	if err != nil { panic(err) }
	defer f.Close()
	img, _, err := image.Decode(f)
	if err != nil { panic(err) }
	return img
}

func scaleRGBA(src image.Image, w, h int, op draw.Interpolator) *image.RGBA {
	dst := image.NewRGBA(image.Rect(0, 0, w, h))
	if op == nil {
		draw.Scale(dst, dst.Bounds(), src, src.Bounds(), draw.Src, nil)
	} else {
		op.Scale(dst, dst.Bounds(), src, src.Bounds(), draw.Src)
	}
	return dst
}

func printVals(img image.Image, n int) {
	for x := 0; x < n; x++ {
		r, g, b, a := img.At(x, 0).RGBA()
		_ = g; _ = b
		fmt.Printf("%d,", r>>8)
	}
	fmt.Println()
}

func main() {
	src := load("/tmp/t/imp16a.png")
	b := src.Bounds()
	fmt.Println("src bounds", b)
	w := 64
	printVals(scaleRGBA(src, w, 1, draw.NearestNeighbor), w)
	printVals(scaleRGBA(src, w, 1, draw.ApproachNearestNeighbor), w)
	printVals(scaleRGBA(src, w, 1, draw.ApproachLinear), w)
	printVals(scaleRGBA(src, w, 1, draw.CatmullRom), w)
	printVals(scaleRGBA(src, w, 1, nil), w)
}
EOF
