from dec import decode
import subprocess,os
env=dict(os.environ)
def run(args):
    r=subprocess.run(['/workspace/executable']+args, capture_output=True, env=env)
    return (r.stdout+r.stderr).decode('utf-8','replace').rstrip('\n')

BASE={
 'fs':[(1,0,7),(-1,1,3),(0,1,5),(1,1,1)],
 'atkinson':[(1,0,1),(1,1,1),(0,1,1),(-1,1,1),(0,2,1)],
 'jjn':[(1,0,7),(2,0,5),(-2,1,3),(-1,1,5),(0,1,7),(1,1,5),(2,1,3),(-1,2,1),(0,2,3),(1,2,5)],
 'sierra':[(1,0,5),(2,0,3),(-2,1,2),(-1,1,4),(0,1,5),(1,1,4),(2,1,2),(-1,2,2),(0,2,3),(1,2,2)],
 'sierralite':[(1,0,2),(-1,1,1),(0,1,2),(1,1,1)],
 'stucki':[(1,0,8),(2,0,4),(-2,1,2),(-1,1,4),(0,1,8),(1,1,4),(2,1,2),(-2,2,1),(-1,2,2),(0,2,4),(1,2,2),(2,2,1)],
 'burkes':[(1,0,8),(2,0,4),(-2,1,2),(-1,1,4),(0,1,8),(1,1,4),(2,1,2)],
}
def rot(k,n):
    for _ in range(n):
        k=[(-dy,dx,w) for dx,dy,w in k]
    return k
def refl(k):
    return [(-dx,dy,w) for dx,dy,w in k]
def norm(k):
    s=sum(w for _,_,w in k)
    return [(dx,dy,w/s) for dx,dy,w in k]

def dither(w,h,img,name,rot_n,refl,order,cmpop,clamp,scale=1.0):
    K=norm(rot(BASE[name],rot_n))
    if refl: K=[(-dx,dy,w) for dx,dy,w in K]
    K=[(dx,dy,w*scale) for dx,dy,w in K]
    vals=[row[:] for row in img]
    on=[[0]*w for _ in range(h)]
    def each():
        if order=='raster':
            for y in range(h):
                for x in range(w): yield y,x
        elif order=='serp':
            for y in range(h):
                if y%2==0:
                    for x in range(w): yield y,x
                else:
                    for x in range(w-1,-1,-1): yield y,x
        elif order=='col':
            for x in range(w):
                for y in range(h): yield y,x
        elif order=='colserp':
            for x in range(w):
                if x%2==0:
                    for y in range(h): yield y,x
                else:
                    for y in range(h-1,-1,-1): yield y,x
    for y,x in each():
        old=vals[y][x]
        new=255 if (old>=128 if cmpop=='ge' else old>128) else 0
