)

func main() {
	for _, n := range []int{1, 2, 3, 5} {
		g := &gif.GIF{Delay: make([]int, n), LoopCount: 0}
		for i := 0; i < n; i++ {
			img := image.NewPaletted(image.Rect(0, 0, 20, 20), color.Palette{color.Gray{uint8(i * 60)}, color.Gray{255}})
