				for x := 0; x < 20; x++ {
					img.Set(x, y, color.Gray{uint8(i * 60)})
				}
			}
			g.Image = append(g.Image, img)
			g.Delay[i] = 10
		}
		f, _ := os.Create("/tmp/t/gif" + strconv.Itoa(n) + ".gif")
		gif.EncodeAll(f, g)
		f.Close()
	}
	// png for reference
	img := image.NewRGBA(image.Rect(0, 0, 20, 20))
	for y := 0; y < 20; y++ {
		for x := 0; x < 20; x++ {
			img.Set(x, y, color.Gray{60})
		}
	}
	f, _ := os.Create("/tmp/t/gray60.png")
	png.Encode(f, img)
	f.Close()
}
