}

var versionDef = flagDef{"version", "v", kindBool, "Version for ascii-image-converter"}

// Options holds the parsed command line state.
type Options struct {
	Color      bool
	ColorBG    bool
	Dimensions []int
	Width      int
	Height     int
	Map        string
	Braille    bool
	Threshold  int
	Dither     bool
	Grayscale  bool
	Complex    bool
	Full       bool
	Negative   bool
	FlipX      bool
	FlipY      bool
	SaveImg    string
	SaveTxt    string
	SaveGif    string
	SaveBG     []int
	Font       string
	FontColor  []int
	OnlySave   bool
	Formats    bool
	Help       bool
	Version    bool

	fontColorSeen bool
	saveBGSeen    bool
	args          []string
}

func flagByName(name string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].name == name {
			return &flagDefs[i]
		}
	}
	if versionDef.name == name {
		return &versionDef
	}
	return nil
}

func flagByShort(s string) *flagDef {
	for i := range flagDefs {
		if flagDefs[i].short == s {
			return &flagDefs[i]
		}
	}
	if versionDef.short == s {
		return &versionDef
	}
	return nil
}

func defLabel(d *flagDef) string {
	if d.short != "" {
		return "-" + d.short + ", --" + d.name
	}
	return "--" + d.name
}

// parseBool mimics pflag's boolean value parsing.
func parseBool(d *flagDef, raw string) (bool, error) {
	v, err := strconv.ParseBool(raw)
	if err != nil {
		return false, fmt.Errorf("invalid argument %q for %q flag: strconv.ParseBool: parsing %q: invalid syntax", raw, defLabel(d), raw)
	}
	return v, nil
}

