func parseInt(d *flagDef, raw string) (int, error) {
	v, err := strconv.ParseInt(raw, 0, strconv.IntSize)
	if err != nil {
		ne := err.(*strconv.NumError)
		return 0, fmt.Errorf("invalid argument %q for %q flag: strconv.ParseInt: parsing %q: %s", raw, defLabel(d), raw, ne.Err.Error())
	}
	return int(v), nil
}

func parseInts(d *flagDef, raw string) ([]int, error) {
	parts := strings.Split(raw, ",")
	out := make([]int, 0, len(parts))
	for _, p := range parts {
		v, err := strconv.Atoi(p)
		if err != nil {
			ne := err.(*strconv.NumError)
			return nil, fmt.Errorf("invalid argument %q for %q flag: strconv.Atoi: parsing %q: %s", raw, defLabel(d), p, ne.Err.Error())
		}
		out = append(out, v)
	}
	return out, nil
}

func (o *Options) setBool(d *flagDef, raw string) error {
	v, err := parseBool(d, raw)
	if err != nil {
		return err
	}
	switch d.name {
	case "color":
		o.Color = v
	case "color-bg":
		o.ColorBG = v
	case "braille":
		o.Braille = v
	case "dither":
		o.Dither = v
	case "grayscale":
		o.Grayscale = v
	case "complex":
		o.Complex = v
	case "full":
		o.Full = v
	case "negative":
		o.Negative = v
	case "flipX":
		o.FlipX = v
	case "flipY":
		o.FlipY = v
	case "only-save":
		o.OnlySave = v
	case "formats":
		o.Formats = v
	case "help":
		o.Help = v
	case "version":
		o.Version = v
	}
	return nil
}

func (o *Options) setInt(d *flagDef, raw string) error {
	v, err := parseInt(d, raw)
	if err != nil {
		return err
	}
	switch d.name {
	case "width":
		o.Width = v
	case "height":
		o.Height = v
	case "threshold":
		o.Threshold = v
	}
	return nil
}

func (o *Options) setString(d *flagDef, raw string) {
	switch d.name {
	case "map":
		o.Map = raw
	case "save-img":
		o.SaveImg = raw
	case "save-txt":
		o.SaveTxt = raw
	case "save-gif":
		o.SaveGif = raw
	case "font":
		o.Font = raw
	}
}

func (o *Options) setInts(d *flagDef, raw string) error {
	v, err := parseInts(d, raw)
	if err != nil {
		return err
	}
	switch d.name {
	case "dimensions":
		o.Dimensions = append(o.Dimensions, v...)
	case "save-bg":
		o.SaveBG = append(o.SaveBG, v...)
		o.saveBGSeen = true
	case "font-color":
		o.FontColor = append(o.FontColor, v...)
		o.fontColorSeen = true
	}
	return nil
}

// ParseFlags parses the command line arguments, returning an error that
// mirrors pflag's error strings.
func ParseFlags(args []string) (*Options, error) {
	o := &Options{Threshold: -1}
	i := 0
	for i < len(args) {
		a := args[i]
		i++
		switch {
		case a == "--":
			o.args = append(o.args, args[i:]...)
			i = len(args)
		case strings.HasPrefix(a, "--"):
			body := a[2:]
			name := body
			var value string
			hasValue := false
			if idx := strings.Index(body, "="); idx >= 0 {
				name = body[:idx]
				value = body[idx+1:]
				hasValue = true
			}
			d := flagByName(name)
			if d == nil {
				return nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if d.kind == kindBool {
				if !hasValue {
					value = "true"
				}
				if err := o.setBool(d, value); err != nil {
					return nil, err
				}
				continue
			}
			if !hasValue {
				if i >= len(args) {
					return nil, fmt.Errorf("flag needs an argument: --%s", name)
				}
				value = args[i]
				i++
			}
			var err error
			switch d.kind {
			case kindInt:
				err = o.setInt(d, value)
			case kindString:
				o.setString(d, value)
			case kindInts:
				err = o.setInts(d, value)
			}
			if err != nil {
				return nil, err
			}
		case len(a) > 1 && a[0] == '-':
			shorthands := a[1:]
			for len(shorthands) > 0 {
				c := string(shorthands[0])
				d := flagByShort(c)
				if d == nil {
					return nil, fmt.Errorf("unknown shorthand flag: %q in -%s", shorthands[0], shorthands)
				}
				if d.kind == kindBool {
					if err := o.setBool(d, "true"); err != nil {
						return nil, err
					}
					shorthands = shorthands[1:]
					continue
				}
				var value string
				if len(shorthands) > 2 && shorthands[1] == '=' {
					value = shorthands[2:]
					shorthands = ""
				} else if len(shorthands) > 1 {
					value = shorthands[1:]
					shorthands = ""
				} else if i < len(args) {
					value = args[i]
					i++
					shorthands = ""
				} else {
					return nil, fmt.Errorf("flag needs an argument: %q in -%s", shorthands[0], shorthands)
				}
				var err error
				switch d.kind {
				case kindInt:
					err = o.setInt(d, value)
				case kindString:
					o.setString(d, value)
				case kindInts:
					err = o.setInts(d, value)
				}
				if err != nil {
					return nil, err
				}
			}
		default:
			o.args = append(o.args, a)
		}
	}
	if !o.fontColorSeen {
		o.FontColor = []int{255, 255, 255}
	}
	if !o.saveBGSeen {
		o.SaveBG = []int{0, 0, 0, 100}
	}
	if o.Threshold < 0 {
		o.Threshold = 128
	}
	return o, nil
}
