package main

import (
	"image"
	"image/color"
	"math"
)

// lanczosKernel implements the Lanczos (a=3) window function.
func lanczosKernel(x float64) float64 {
	if x < -3 || x >= 3 {
		return 0
	}
	return sinc(x) * sinc(x/3)
}

func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	px := math.Pi * x
	return math.Sin(px) / px
}

// coeffs1D builds the normalized weight table for one axis.
func coeffs1D(srcLen, dstLen int) [][]float64 {
	scale := float64(srcLen) / float64(dstLen)
	out := make([][]float64, dstLen)
	halfWidth := 3.0
	if scale > 1 {
		halfWidth = math.Ceil(3 * scale)
	}
	for dx := 0; dx < dstLen; dx++ {
		center := (float64(dx)+0.5)*scale - 0.5
		lo := int(math.Floor(center - halfWidth))
		hi := int(math.Ceil(center + halfWidth))
		if lo < 0 {
			lo = 0
		}
		if hi > srcLen-1 {
			hi = srcLen - 1
		}
		ws := make([]float64, srcLen)
		sum := 0.0
		for i := lo; i <= hi; i++ {
			var k float64
			if scale > 1 {
				k = lanczosKernel((center - float64(i)) / scale)
			} else {
				k = lanczosKernel(center - float64(i))
			}
			ws[i] = k
			sum += k
		}
		if sum != 0 {
			for i := range ws {
				ws[i] /= sum
			}
		}
		out[dx] = ws
	}
	return out
}

func clamp8(v float64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(math.Floor(v + 0.5))
}

// scaleRGBA resizes src to the given dimensions using a separable Lanczos
// filter, matching the reference implementation (one pass per axis with the
// intermediate result clamped to the 8 bit range).
func scaleRGBA(src image.Image, newW, newH int) *image.RGBA {
	b := src.Bounds()
	srcW, srcH := b.Dx(), b.Dy()
	// Materialise the source as premultiplied RGBA first.
	conv := image.NewRGBA(image.Rect(0, 0, srcW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < srcW; x++ {
			conv.Set(x, y, src.At(b.Min.X+x, b.Min.Y+y))
		}
	}
	kx := coeffs1D(srcW, newW)
	tmp := make([][]uint8, srcH)
	for j := 0; j < srcH; j++ {
		row := make([]uint8, newW*4)
		srcPix := conv.Pix[j*conv.Stride:]
		for x := 0; x < newW; x++ {
			ws := kx[x]
			var r, g, bl, a float64
			for i := 0; i < srcW; i++ {
				w := ws[i]
				if w == 0 {
					continue
				}
				o := i * 4
				r += w * float64(srcPix[o])
				g += w * float64(srcPix[o+1])
				bl += w * float64(srcPix[o+2])
				a += w * float64(srcPix[o+3])
			}
			row[x*4] = clamp8(r)
			row[x*4+1] = clamp8(g)
			row[x*4+2] = clamp8(bl)
			row[x*4+3] = clamp8(a)
		}
		tmp[j] = row
	}
	ky := coeffs1D(srcH, newH)
	dst := image.NewRGBA(image.Rect(0, 0, newW, newH))
	for y := 0; y < newH; y++ {
		ws := ky[y]
		outPix := dst.Pix[y*dst.Stride:]
		for x := 0; x < newW; x++ {
			var r, g, bl, a float64
			for j := 0; j < srcH; j++ {
				w := ws[j]
				if w == 0 {
					continue
				}
				o := x * 4
				p := tmp[j]
				r += w * float64(p[o])
				g += w * float64(p[o+1])
				bl += w * float64(p[o+2])
				a += w * float64(p[o+3])
			}
			outPix[x*4] = clamp8(r)
			outPix[x*4+1] = clamp8(g)
			outPix[x*4+2] = clamp8(bl)
			outPix[x*4+3] = clamp8(a)
		}
	}
	return dst
}

// grayOf returns the 8 bit grayscale value for a premultiplied RGBA pixel,
// matching color.GrayModel's conversion.
func grayOf(r, g, b, a uint8) uint8 {
	r16 := uint32(r) * 0x101
	g16 := uint32(g) * 0x101
	b16 := uint32(b) * 0x101
	y := (299*r16 + 587*g16 + 114*b16 + 500) / 1000
	return uint8(y >> 8)
}

func grayAt(img *image.RGBA, x, y int) uint8 {
	o := img.PixOffset(x, y)
	return grayOf(img.Pix[o], img.Pix[o+1], img.Pix[o+2], img.Pix[o+3])
}

var _ = color.RGBAModel
