// lanczosKernel implements the Lanczos (a=3) window function.
func lanczosKernel(x float64) float64 {
	if x < -3 || x >= 3 {
		return 0
	}
	return sinc(x) * sinc(x/3)
}

func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	px := math.Pi * x
	return math.Sin(px) / px
}

// coeffs1D builds the normalized weight table for one axis.
func coeffs1D(srcLen, dstLen int) [][]float64 {
	scale := float64(srcLen) / float64(dstLen)
	out := make([][]float64, dstLen)
	halfWidth := 3.0
	if scale > 1 {
		halfWidth = math.Ceil(3 * scale)
	}
	for dx := 0; dx < dstLen; dx++ {
		center := (float64(dx)+0.5)*scale - 0.5
		lo := int(math.Floor(center - halfWidth))
		hi := int(math.Ceil(center + halfWidth))
		if lo < 0 {
			lo = 0
		}
		if hi > srcLen-1 {
			hi = srcLen - 1
		}
		ws := make([]float64, srcLen)
		sum := 0.0
		for i := lo; i <= hi; i++ {
			var k float64
			if scale > 1 {
				k = lanczosKernel((center - float64(i)) / scale)
			} else {
				k = lanczosKernel(center - float64(i))
			}
			ws[i] = k
			sum += k
		}
		if sum != 0 {
			for i := range ws {
				ws[i] /= sum
			}
		}
		out[dx] = ws
	}
	return out
}

func clamp8(v float64) uint8 {
	if v < 0 {
		return 0
	}
	if v > 255 {
		return 255
	}
	return uint8(math.Floor(v + 0.5))
}

// scaleRGBA resizes src to the given dimensions using a separable Lanczos
// filter, matching the reference implementation (one pass per axis with the
// intermediate result clamped to the 8 bit range).
func scaleRGBA(src image.Image, newW, newH int) *image.RGBA {
