	conv := image.NewRGBA(image.Rect(0, 0, srcW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < srcW; x++ {
			conv.Set(x, y, src.At(b.Min.X+x, b.Min.Y+y))
		}
	}
	kx := coeffs1D(srcW, newW)
	tmp := make([][]uint8, srcH)
	for j := 0; j < srcH; j++ {
		row := make([]uint8, newW*4)
