				g += w * float64(p[o+1])
				bl += w * float64(p[o+2])
				a += w * float64(p[o+3])
			}
			outPix[x*4] = clamp8(r)
			outPix[x*4+1] = clamp8(g)
			outPix[x*4+2] = clamp8(bl)
			outPix[x*4+3] = clamp8(a)
		}
	}
	return dst
}

