package main

import (
	"image"
)

var defaultCharMap = " .:-=+*#%@"
var complexCharMap = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0zmwqpdbkhao*#MW&8%B@$"

// asciiCharMap resolves the character ramp for the conversion.
func asciiCharMap(o *Options) string {
	switch {
	case o.Map != "":
		return o.Map
	case o.Complex:
		return complexCharMap
	}
	return defaultCharMap
}

func invertIndex(i, n int) int { return n - 1 - i }

// charIndex maps a gray value to a position in the character ramp.
func charIndex(gray uint8, l int) int {
	idx := int(uint32(gray) * uint32(l) / 255)
	if idx > l-1 {
		idx = l - 1
	}
	return idx
}

func flipHorizontal(lines []string) {
	for i := range lines {
		r := []rune(lines[i])
		for a, b := 0, len(r)-1; a < b; a, b = a+1, b-1 {
			r[a], r[b] = r[b], r[a]
		}
		lines[i] = string(r)
	}
}

func flipVertical(lines []string) {
	for a, b := 0, len(lines)-1; a < b; a, b = a+1, b-1 {
		lines[a], lines[b] = lines[b], lines[a]
	}
}

// convertToAsciiChars performs the ascii (non braille) conversion.
func convertToAsciiChars(img *image.RGBA, cols, rows int, o *Options, support colorSupport) ([]string, []colorSpec) {
	scaled := scaleRGBA(img, cols, rows)
	charMap := asciiCharMap(o)
	l := len([]rune(charMap))
	runes := []rune(charMap)
	lines := make([]string, rows)
	colors := make([]colorSpec, 0, cols*rows)
	for y := 0; y < rows; y++ {
		var b []rune
		for x := 0; x < cols; x++ {
			off := scaled.PixOffset(x, y)
			r, g, bl, a := scaled.Pix[off], scaled.Pix[off+1], scaled.Pix[off+2], scaled.Pix[off+3]
			gray := grayOf(r, g, bl, a)
			idx := charIndex(gray, l)
			if o.Negative {
				idx = invertIndex(idx, l)
			}
			b = append(b, runes[idx])
			colors = append(colors, colorSpec{r: r, g: g, b: bl, gray: gray})
		}
		lines[y] = string(b)
	}
	return lines, colors
}

// convertToBraille performs the braille conversion.
func convertToBraille(img *image.RGBA, cols, rows int, o *Options, support colorSupport) ([]string, []colorSpec) {
	scaled := scaleRGBA(img, cols*2, rows*4)
	grays := make([][]uint8, rows*4)
	for y := 0; y < rows*4; y++ {
		grays[y] = make([]uint8, cols*2)
		for x := 0; x < cols*2; x++ {
			off := scaled.PixOffset(x, y)
			grays[y][x] = grayOf(scaled.Pix[off], scaled.Pix[off+1], scaled.Pix[off+2], scaled.Pix[off+3])
		}
	}
	if o.Dither {
		ditherGrays(grays, o.Threshold)
	}
	bits := [8][2]int{{0, 0}, {1, 0}, {2, 0}, {0, 1}, {1, 1}, {2, 1}, {3, 0}, {3, 1}}
	lines := make([]string, rows)
	colors := make([]colorSpec, 0, cols*rows)
	for cy := 0; cy < rows; cy++ {
		var b []rune
		for cx := 0; cx < cols; cx++ {
			code := 0
			for i, p := range bits {
				gray := grays[cy*4+p[0]][cx*2+p[1]]
				if int(gray) >= o.Threshold {
					code |= 1 << i
				}
			}
			b = append(b, rune(0x2800+code))
			off := scaled.PixOffset(cx*2, cy*4)
			r, g, bl, a := scaled.Pix[off], scaled.Pix[off+1], scaled.Pix[off+2], scaled.Pix[off+3]
			colors = append(colors, colorSpec{r: r, g: g, b: bl, gray: grayOf(r, g, bl, a)})
		}
		lines[cy] = string(b)
	}
	return lines, colors
}

// ditherGrays applies error diffusion in place.
func ditherGrays(grays [][]uint8, threshold int) {
	h := len(grays)
	w := len(grays[0])
	vals := make([][]float64, h)
	for y := range grays {
		vals[y] = make([]float64, w)
		for x := range grays[y] {
			vals[y][x] = float64(grays[y][x])
		}
	}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			old := vals[y][x]
			var new float64
			if int(old) >= threshold {
				new = 255
			}
			err := old - new
			if x+1 < w {
				vals[y][x+1] += err * 7 / 16
			}
			if y+1 < h {
				if x-1 >= 0 {
					vals[y+1][x-1] += err * 3 / 16
				}
				vals[y+1][x] += err * 5 / 16
				if x+1 < w {
					vals[y+1][x+1] += err * 1 / 16
				}
			}
			if new > 0 {
				grays[y][x] = 255
			} else {
				grays[y][x] = 0
			}
		}
	}
}

// colorSpec carries the per character colour information.
type colorSpec struct {
	r, g, b uint8
	gray    uint8
}
