		if o.Dimensions[0] <= 0 || o.Dimensions[1] <= 0 {
			return fmt.Errorf("invalid values for dimensions")
		}
	}
	if o.SaveBG != nil {
		if len(o.SaveBG) != 4 {
			return fmt.Errorf("--save-bg requires 4 values for RGBA, got %d", len(o.SaveBG))
		}
		bgOK := true
		for _, v := range o.SaveBG[:3] {
			if v < 0 || v > 255 {
				bgOK = false
			}
		}
		opOK := o.SaveBG[3] >= 0 && o.SaveBG[3] <= 100
		if !bgOK || !opOK {
			fmt.Println("Error: RBG values must be between 0 and 255")
			fmt.Println("Error: Opacity value must be between 0 and 100")
			return fmt.Errorf("invalid save background")
		}
	}
	if o.FontColor != nil {
		if len(o.FontColor) != 3 {
			return fmt.Errorf("--font-color requires 3 values for RGB, got %d", len(o.FontColor))
		}
		for _, v := range o.FontColor {
			if v < 0 || v > 255 {
				return fmt.Errorf("RBG values must be between 0 and 255")
			}
		}
	}
	if o.Braille && (o.Threshold < 0 || o.Threshold > 255) {
		return fmt.Errorf("threshold must be between 0 and 255")
	}
	if o.Dither && !o.Braille {
		return fmt.Errorf("image dithering is only reserved for --braille flag")
	}
	return nil
}

func isURLPath(p string) bool {
	return strings.HasPrefix(p, "http://") || strings.HasPrefix(p, "https://")
}

func fetchURL(raw string) ([]byte, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return nil, err
	}
	resp, err := http.Get(u.String())
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	return io.ReadAll(resp.Body)
}

func baseNameOf(p string) string {
	if isURLPath(p) {
		u, err := url.Parse(p)
		if err == nil {
			p = u.Path
		}
	}
	base := filepath.Base(p)
	if idx := strings.LastIndex(base, "."); idx > 0 {
		base = base[:idx]
	}
	return base
}

// stdinHasPipedInput reports whether stdin is a character device (terminal,
// /dev/null, ...) rather than a pipe or regular file.
func stdinHasPipedInput() bool {
	st, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return st.Mode()&os.ModeCharDevice != 0
}

func readStdin() ([]byte, error) {
	if stdinHasPipedInput() {
		return nil, errNoPipedInput
	}
	return io.ReadAll(bufio.NewReader(os.Stdin))
}

type simpleError string

func (e simpleError) Error() string { return string(e) }

const errNoPipedInput = simpleError("there is no input being piped to stdin")

// convertInput handles a single input source end to end.
func convertInput(o *Options, arg string, data []byte, name string) {
	if arg == "-" {
		b, err := readStdin()
		if err != nil {
			fmt.Println("Error:", err)
			return
		}
		data = b
		name = "piped input"
	} else if isURLPath(arg) {
		fmt.Printf("Fetching file from url...\r%s\r", strings.Repeat(" ", len("Fetching file from url...")+2))
		b, err := fetchURL(arg)
		if err != nil {
			fmt.Printf("Error: can't fetch content: %v\n", err)
			return
		}
		data = b
		name = arg
	} else {
		b, err := os.ReadFile(arg)
		if err != nil {
			fmt.Printf("Error: unable to open file: %v\n", err)
			return
		}
		data = b
		name = arg
	}
	runConversion(o, data, name)
}
