func dirExists(p string) bool {
	st, err := os.Stat(strings.TrimSuffix(p, "/"))
	return err == nil && st.IsDir()
}

func printArt(o *Options, all [][]string, allColors [][]colorSpec, support colorSupport, fs *frameSet) {
	if fs.isGif && len(fs.frames) > 0 {
		n := len(fs.frames)
		delays := make([]time.Duration, n)
		for i := 0; i < n; i++ {
			d := 10
			if i < len(fs.delays) {
				d = fs.delays[i]
			}
			delays[i] = time.Duration(d) * 10 * time.Millisecond
		}
		loopCount := fs.loopCount
		i := 0
		for {
			for j := 0; j < n; j++ {
				lines := all[j]
				colors := allColors[j]
				rendered := renderLines(lines, colors, o, support)
				for _, l := range rendered {
					fmt.Println(l)
				}
				time.Sleep(delays[j])
				if j == 0 && i >= loopCount && n > 1 && loopCount > 0 {
					return
				}
			}
			i++
			if loopCount == 0 || n == 1 {
				continue
			}
			if i >= loopCount+1 {
				return
			}
		}
	}
	for _, lines := range all {
		rendered := renderLines(lines, allColors[0], o, support)
		for _, l := range rendered {
			fmt.Println(l)
		}
	}
}

func panicEmpty() {
	var empty []int
	_ = empty[0]
}
