		dir := strings.TrimSuffix(o.SaveTxt, "/")
		if !dirExists(o.SaveTxt) {
			fmt.Printf("Error: can't save file: save path %s/ does not exist\n", o.SaveTxt)
			return
		}
		path := filepath.Join(dir, base+"-ascii-art.txt")
