	"time"
)

// frameSet holds the decoded animation or single image.
type frameSet struct {
	frames    []*image.RGBA
	delays    []int
	loopCount int
	isGif     bool
}

// decodeAll decodes the raw bytes, returning every frame for animated gifs.
func decodeAll(data []byte) (*frameSet, error) {
	fs := &frameSet{}
	if d, err := gif.DecodeAll(strings.NewReader(string(data))); err == nil {
		fs.isGif = true
		fs.loopCount = d.LoopCount
		for _, f := range d.Image {
			fs.frames = append(fs.frames, toRGBA(f))
		}
		fs.delays = d.Delay
		return fs, nil
	}
	img, _, err := image.Decode(strings.NewReader(string(data)))
	if err != nil {
		return nil, err
	}
	fs.frames = append(fs.frames, toRGBA(img))
	return fs, nil
}

func toRGBA(img image.Image) *image.RGBA {
	if r, ok := img.(*image.RGBA); ok {
		return r
	}
	b := img.Bounds()
	out := image.NewRGBA(image.Rect(0, 0, b.Dx(), b.Dy()))
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			out.Set(x, y, img.At(b.Min.X+x, b.Min.Y+y))
		}
	}
	return out
}

// determineAsciiDims computes the character grid for the conversion.
func determineAsciiDims(imgW, imgH int, o *Options, tw, th int) (int, int) {
	cols, rows := 0, 0
	switch {
	case o.Dimensions != nil:
		cols, rows = o.Dimensions[0], o.Dimensions[1]
	case o.Width != 0:
		cols = o.Width
		rows = cols * imgH / (2 * imgW)
		if rows < 1 {
			rows = 1
		}
	case o.Height != 0:
		rows = o.Height
		cols = 2 * (rows * imgW / imgH)
		if cols < 1 {
			cols = 1
		}
	case o.Full:
		cols = tw - 1
		rows = cols * imgH / (2 * imgW)
		if rows < 1 {
			rows = 1
		}
	default:
		rows = th - 1
		cols = 2 * (rows * imgW / imgH)
		if cols > tw-1 {
			cols = tw - 1
			rows = cols * imgH / (2 * imgW)
		}
		if rows < 1 {
			rows = 1
		}
		if cols < 1 {
			cols = 1
		}
	}
	if o.Braille {
		cols *= 3
	}
	return cols, rows
}

// renderLines converts the per character colours into terminal escape output.
func renderLines(lines []string, colors []colorSpec, o *Options, support colorSupport) []string {
	colorMode := o.Color || o.Grayscale || !isWhite(o.FontColor)
	if !colorMode || support == supportNone {
		return lines
	}
	var b strings.Builder
	idx := 0
	for _, line := range lines {
		for _, ch := range line {
			cs := colors[idx]
			idx++
			b.WriteString(escapeFor(cs, o, support))
			b.WriteRune(ch)
			b.WriteString("\x1b[0m")
		}
		b.WriteString("\n")
	}
	out := strings.Split(strings.TrimSuffix(b.String(), "\n"), "\n")
	for i := range out {
		out[i] = strings.TrimSuffix(out[i], "\n")
	}
	return out
}

func isWhite(c []int) bool {
	return len(c) == 3 && c[0] == 255 && c[1] == 255 && c[2] == 255
}

func pickColor(cs colorSpec, o *Options) (int, int, int) {
	if o.Color {
		r, g, b := int(cs.r), int(cs.g), int(cs.b)
		if o.Negative {
			r, g, b = 255-r, 255-g, 255-b
		}
		return r, g, b
	}
	if o.Grayscale {
		v := int(cs.gray)
		if o.Negative {
			v = 255 - v
		}
		return v, v, v
	}
	return o.FontColor[0], o.FontColor[1], o.FontColor[2]
}

var cubeLevels = []int{0, 95, 135, 175, 215, 255}

func cubeLevel(v int) int {
	best, bd := 0, 1<<30
	for i, l := range cubeLevels {
		d := v - l
		if d < 0 {
			d = -d
		}
		if d < bd {
			bd, best = d, i
		}
	}
	return best
}

func to8Bit(r, g, b int) int {
	lr, lg, lb := cubeLevel(r), cubeLevel(g), cubeLevel(b)
	switch {
	case lr == 0 && lg == 0 && lb == 0:
		return 0
	case lr == 5 && lg == 0 && lb == 0:
		return 9
	case lr == 0 && lg == 5 && lb == 0:
		return 10
	case lr == 5 && lg == 5 && lb == 0:
		return 11
	case lr == 0 && lg == 0 && lb == 5:
		return 12
	case lr == 5 && lg == 0 && lb == 5:
		return 13
	case lr == 0 && lg == 5 && lb == 5:
		return 14
	case lr == 5 && lg == 5 && lb == 5:
		return 15
	}
	return 16 + 36*lr + 6*lg + lb
}

func escapeFor(cs colorSpec, o *Options, support colorSupport) string {
	r, g, b := pickColor(cs, o)
	if o.ColorBG {
		if support == support24bit {
