		}
		return fmt.Sprintf("\x1b[48;5;%dm", to8Bit(r, g, b))
	}
	if support == support24bit {
		return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b)
	}
	return fmt.Sprintf("\x1b[38;5;%dm", to8Bit(r, g, b))
}

